#pragma once
// Three-phase alchemist. Source timers are in icc/Putricide.hpp; native damage,
// puddles, experiment targets, mutations and plague transfer are instance owned.
class PutricideRuntime final:public FestergutRuntime,public ICC::PutricidePort {
 ICC::Putricide professor;entt::entity table=entt::null;uint32_t mutant=0,nextWorld=0,plagueCarrier=0,plagueEnd=0,plagueNext=0,plagueHeld=0;bool failing=false;
 struct Pool {uint32_t id=0;Vec point;float radius=2;uint32_t nextGrow=0,end=0;};std::vector<Pool> pools;
 struct Bomb {Vec point;uint32_t at=0,end=0;bool goo=false;};std::vector<Bomb> bombs;
 struct ExperimentActor {entt::entity entity;uint32_t pid=0,next=0,born=0,slowEnd=0;bool gas=false;unsigned stacks=10;};std::vector<ExperimentActor> experiments;
 std::map<uint32_t,uint32_t> adhesive,energy,sickness;std::map<uint32_t,bool> variables;
 unsigned PlagueStacks(uint32_t pid)const{return Stacks(72451,pid);}
 uint32_t PlagueTank()const{uint32_t result=0;double maximum=-1;for(auto& m:run.members){auto p=Player(m);if(!Alive(run,p))continue;auto it=threat.find(m.pid);double score=(it==threat.end()?0:double(it->second))+1/(1+Distance(Position(p),Position(boss)));score/=std::pow(3.,PlagueStacks(m.pid));if(score>maximum){maximum=score;result=m.pid;}}return result;}
 std::vector<entt::entity> PickPlayers(unsigned count,bool noTank=true){auto list=Living(run);auto tank=PlagueTank();if(noTank&&list.size()>1)list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){return P::GetPlayerID(p)==tank;}),list.end());for(size_t i=list.size();i>1;i--)std::swap(list[i-1],list[random.Uniform(0,uint32_t(i-1))]);if(list.size()>count)list.resize(count);return list;}
 void SetRoot(uint32_t pid,bool value){auto p=Resolve(pid);if(value){run.rooted.insert(pid);if(Alive(run,p))M::Stop(p);}else run.rooted.erase(pid);if(Present(run,p))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_root %d",value?1:0);}
 void Unlock(uint32_t pid){adhesive.erase(pid);if(!professor.Transitioning()||ICC::Heroic(run.mode))SetRoot(pid,false);auto p=Resolve(pid);if(Present(run,p))Fx(70447,4,p,Position(p),0);}
 void ClearMutation(){if(!mutant)return;auto p=Resolve(mutant);if(Present(run,p)){Fx(70311,4,p,Position(p),0);Broadcast(run,"er_actor_scale "+std::to_string(P::GetPacketVID(p))+" 100");Broadcast(run,"er_actor_tint "+std::to_string(P::GetPacketVID(p))+" 255 255 255");}if(auto m=Participant(run,mutant)){m->aura=Mechanic::Strike;m->auraEnd=0;}mutant=0;}
 void DropPool(Vec point){if(pools.size()>=24)return;Pool pool;pool.id=run.nextHazard++;pool.point=point;pool.nextGrow=now+1000;pool.end=now+180000;pools.push_back(pool);ShowPool(pools.back());}
 void ShowPool(Pool& p){std::ostringstream line;line<<"er_hazard "<<run.id<<' '<<p.id<<' '<<int(Mechanic::Slime)<<" 0 "<<BaseX+int(p.point.x*100)<<' '<<BaseY+int(p.point.y*100)<<' '<<int(p.radius*100)<<" 100 0 0 0 1500";Broadcast(run,line.str());Fx(70343,5,entt::null,p.point,1300,p.radius);}
 void HealBoss(uint64_t amount){if(Valid(boss)&&!CombatSystem::IsDead(boss))P::SetHP(boss,std::min<uint64_t>(Points::GetMaxHP(boss),uint64_t(P::GetHP(boss))+amount));}
 void PlagueEvent(const ICC::AuraEvent& e){auto spell=e.aura.spec.key.spell,pid=e.aura.spec.key.target;auto p=Resolve(pid);if(spell!=72451){Periodic(e);return;}if(e.removed){if(e.reason!=ICC::AuraRemoval::EncounterReset&&Valid(boss)){auto healID=uint32_t(std::max<int64_t>(0,Value(72451)));auto healing=Spell(healID);if(healing)HealBoss(uint64_t(std::max<int64_t>(0,Value(healID)))*e.aura.stacks);}if(Present(run,p))Fx(spell,4,p,Position(p),0);return;}auto source=Spell(spell);auto triggered=source?uint32_t(std::max(0,source->effects[0].trigger)):0;auto damage=std::max<int64_t>(1,Value(triggered))*std::pow(2.5,double(std::min(10u,e.aura.stacks)));for(auto other:Living(run))Damage(other,int64_t(std::min<double>(damage,1e12)));}
 void TickPlague(){if(!plagueCarrier)return;auto p=Resolve(plagueCarrier);if(!Alive(run,p)||Due(now,plagueEnd)){if(Present(run,p))Fx(70911,4,p,Position(p),0);plagueCarrier=0;return;}if(Due(now,plagueNext)){plagueNext=now+1000;auto age=(now-plagueHeld)/1000;Damage(p,int64_t(std::max<int64_t>(1,Value(70911)))*std::max(1u,age));if(age>=2){for(auto other:Living(run)){auto pid=P::GetPlayerID(other);if(pid==plagueCarrier||!Due(now,sickness[pid])||Distance(Position(other),Position(p))>3)continue;sickness[plagueCarrier]=now+60000;Fx(70911,4,p,Position(p),0);plagueCarrier=pid;plagueHeld=now;Fx(70911,3,other,Position(other),plagueEnd-now);Notice(run,"ER_PUTRI_PLAGUE_TRANSFER");break;}}}}
public:
 explicit PutricideRuntime(Run& r):FestergutRuntime(r,false),professor(r.id^0x701){run.phase=1;professor.Reset(*this);Vec at{Arenas[6].center.x-20,Arenas[6].center.y-15};table=Spawn(run,62016,at,2,0,0);if(!Valid(table))failing=true;Notice(run,"ER_PUTRI_BEGIN");}
 ~PutricideRuntime()override{ClearMutation();for(auto& member:run.members){auto p=Player(member);if(Valid(p))AffectSystem::RemoveAffect(p,62047);}for(auto pid:std::vector<uint32_t>(run.rooted.begin(),run.rooted.end()))SetRoot(pid,false);}
 ICC::Difficulty Mode()const override{return run.mode;}
 void Ability(uint32_t id)override{
  M::Stop(boss);M::SendMovePacket(boss,FUNC_MOB_SKILL,0,P::GetX(boss),P::GetY(boss),0);
  if(id==26662){berserk=true;Fx(id,3,boss,Position(boss),600000);Notice(run,"ER_ENRAGE");return;}
  if(id==70341){for(auto p:PickPlayers(2,false))DropPool(Position(p));return;}
  if(id==70852){for(auto p:PickPlayers(ICC::RaidMode<unsigned>(run.mode,1,2,1,3))){auto at=Position(p);if(bombs.size()<24){bombs.push_back({at,now+2500,now+4000,true});Emit(at,2500,1000,int(Mechanic::Gas),5);Fx(id,1,p,at,2500);}}return;}
  if(id==71255){auto at=Position(boss);for(float side:{-1.f,1.f})if(bombs.size()<24){Vec point{at.x+side*4,at.y-3};bombs.push_back({point,now+2000,now+22000,false});Emit(point,2000,20000,int(Mechanic::Gas),5);Fx(id,5,entt::null,point,20000,5);}return;}
  if(id==72451){auto p=Resolve(PlagueTank());if(Alive(run,p))Apply(id,P::GetPlayerID(p),10);return;}
  if(id==70911&&!plagueCarrier){auto list=PickPlayers(1);if(!list.empty()){auto p=list.front();plagueCarrier=P::GetPlayerID(p);plagueHeld=now;plagueEnd=now+60000;plagueNext=now+1000;Fx(id,3,p,Position(p),60000);Notice(run,"ER_PUTRI_UNBOUND");}}
 }
 void Experiment(bool gas)override{if(experiments.size()>=12)return;auto candidates=PickPlayers(30);candidates.erase(std::remove_if(candidates.begin(),candidates.end(),[&](auto p){auto pid=P::GetPlayerID(p);return pid==mutant||adhesive.count(pid)||(ICC::Heroic(run.mode)&&ICC::Raid25(run.mode)&&variables.count(pid)&&variables[pid]!=gas);}),candidates.end());if(candidates.empty())return;auto p=candidates.front();auto pid=P::GetPlayerID(p);Vec at{Arenas[6].center.x+(gas?25.f:-25.f),Arenas[6].center.y+15};auto e=Spawn(run,gas?62028:62027,at,1,0,gas?37562:37697);if(!Valid(e)){failing=true;return;}experiments.push_back({e,pid,now+1000,now,0,gas,10});Fx(gas?70672:70447,3,p,Position(p),600000,0,e);if(!gas){adhesive[pid]=P::GetPacketVID(e);SetRoot(pid,true);}Notice(run,gas?"ER_PUTRI_GAS":"ER_PUTRI_OOZE");}
 void Transition(unsigned phase,bool heroic)override{run.phase=int(phase);M::Stop(boss);Fx(phase==2?71621:71893,0,boss,Position(boss),heroic?49000:24000);variables.clear();if(heroic&&ICC::Raid25(run.mode)){unsigned i=0;for(auto p:Living(run))variables[P::GetPlayerID(p)]=(i++%2)!=0;}if(!heroic)for(auto p:Living(run)){SetRoot(P::GetPlayerID(p),true);Fx(71617,3,p,Position(p),24000);}if(phase==3){Destroy(table);table=entt::null;ClearMutation();}Notice(run,phase==2?"ER_PUTRI_PHASE_TWO":"ER_PUTRI_PHASE_THREE");}
 void Resume(unsigned)override{variables.clear();for(auto& member:run.members){auto p=Player(member);if(Present(run,p))Fx(71617,4,p,Position(p),0);SetRoot(member.pid,adhesive.count(member.pid)!=0);}Fx(71621,4,boss,Position(boss),0);Fx(71893,4,boss,Position(boss),0);}
 bool Action(entt::entity p,const std::string& action,uint32_t)override{
  auto pid=P::GetPlayerID(p);if(action=="interact"){if(mutant||professor.Phase()==3||!Valid(table)||Distance(Position(p),Position(table))>6){Notice(p,"ER_PUTRI_TABLE_UNAVAILABLE");return true;}mutant=pid;energy[pid]=0;Aura(run,p,Mechanic::Mutation,600000);Fx(70311,3,p,Position(p),600000);Broadcast(run,"er_actor_scale "+std::to_string(P::GetPacketVID(p))+" 120");Broadcast(run,"er_actor_tint "+std::to_string(P::GetPacketVID(p))+" 110 210 95");Notice(run,"ER_PUTRI_MUTANT");return true;}
  if(action!="mutate"&&action!="slow")return false;if(mutant!=pid||professor.Phase()==3){Notice(p,"ER_PUTRI_NEED_MUTATION");return true;}
  if(action=="mutate"){auto chosen=pools.end();float distance=12;for(auto i=pools.begin();i!=pools.end();++i)if(auto d=Distance(Position(p),i->point);d<distance){chosen=i;distance=d;}if(chosen==pools.end()){Notice(p,"ER_PUTRI_NEAR_POOL");return true;}chosen->radius-=1.5f;energy[pid]=std::min(100u,energy[pid]+20);if(chosen->radius<.5f){pools.erase(chosen);}return true;}
  if(energy[pid]<50){Notice(p,"ER_PUTRI_NEED_ENERGY");return true;}for(auto& a:experiments)if(Valid(a.entity)&&Distance(Position(p),Position(a.entity))<30){energy[pid]-=50;a.slowEnd=now+20000;AffectSystem::RemoveAffect(a.entity,62046);AffectSystem::AddAffect(a.entity,62046,POINT_MOV_SPEED,-50,0,20,0,true);Fx(70539,3,a.entity,Position(a.entity),20000);return true;}return true;
 }
 int64_t Outgoing(entt::entity,int64_t damage)override{return damage;}
 int64_t TargetDamage(entt::entity attacker,entt::entity target,int64_t amount)override{if(target==boss){if(professor.Transitioning())return 0;unsigned phase=professor.Phase();if(phase<3){auto hp=std::max<int64_t>(0,P::GetHP(boss)),maxHP=std::max<int64_t>(1,Points::GetMaxHP(boss));auto threshold=maxHP*(phase==1?80:35)/100;if(amount>=hp-threshold){professor.Health(*this,phase==1?80:35);return std::max<int64_t>(0,hp-threshold);}}}if(ICC::Heroic(run.mode)&&ICC::Raid25(run.mode)&&variables.count(P::GetPlayerID(attacker)))for(auto& a:experiments)if(a.entity==target&&variables[P::GetPlayerID(attacker)]!=a.gas)return 0;return amount;}
 bool Dispel(entt::entity)override{return false;}
 void Died(entt::entity actor)override{if(actor==boss)return;for(auto& a:experiments)if(a.entity==actor&&!a.gas)Unlock(a.pid);if(P::IsPC(actor)){auto pid=P::GetPlayerID(actor);auras.RemoveTarget(pid,ICC::AuraRemoval::Death);Unlock(pid);if(mutant==pid)ClearMutation();}}
 void Status(entt::entity p)override{FestergutRuntime::Status(p);ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_putri %u %u %u %u %u",run.id,professor.Phase(),mutant,P::GetPlayerID(p)==mutant?energy[mutant]:0,plagueCarrier);}
 bool Update(uint32_t time)override{now=time;auto elapsed=now-last;last=now;if(!Valid(boss)||CombatSystem::IsDead(boss))return true;professor.Health(*this,unsigned(uint64_t(P::GetHP(boss))*100/std::max<int64_t>(1,Points::GetMaxHP(boss))));professor.Tick(*this,elapsed);auras.Advance(elapsed,[](auto&){},0);for(auto& m:run.members)if(!Alive(run,Player(m)))auras.RemoveTarget(m.pid,ICC::AuraRemoval::Death);auras.Advance(0,[&](auto& e){PlagueEvent(e);});TickPlague();
  for(size_t i=0;i<pools.size();){auto& pool=pools[i];if(Due(now,pool.end)){pools.erase(pools.begin()+i);continue;}if(Due(now,pool.nextGrow)){pool.nextGrow=now+1000;pool.radius=std::min(12.f,pool.radius+.18f);ShowPool(pool);for(auto p:Living(run))if(P::GetPlayerID(p)!=mutant&&Distance(Position(p),pool.point)<=pool.radius)Damage(p,Value(70343));}++i;}
  for(size_t i=0;i<bombs.size();){auto b=bombs[i];if(Due(now,b.end)){bombs.erase(bombs.begin()+i);continue;}if(!Due(now,b.at)){++i;continue;}bombs[i].at=now+1000;Fx(b.goo?70853:71279,5,entt::null,b.point,1300,5);for(auto p:Living(run))if(Distance(Position(p),b.point)<=5){Damage(p,Value(b.goo?70853:71279));if(b.goo)GooSlow(p);}if(b.goo)bombs.erase(bombs.begin()+i);else ++i;}
  for(size_t i=0;i<experiments.size();){auto& a=experiments[i];if(!Valid(a.entity)||CombatSystem::IsDead(a.entity)){if(!a.gas)Unlock(a.pid);Destroy(a.entity);experiments.erase(experiments.begin()+i);continue;}auto p=Resolve(a.pid);if(!Alive(run,p)){if(!a.gas)Unlock(a.pid);Destroy(a.entity);experiments.erase(experiments.begin()+i);continue;}float d=Distance(Position(a.entity),Position(p));if(d<3){auto point=Position(p);if(a.gas){auto damage=std::max<int64_t>(1,Value(70701))*a.stacks;for(auto other:Living(run))Damage(other,damage);}else{std::vector<entt::entity> near;for(auto other:Living(run))if(Distance(Position(other),point)<=10)near.push_back(other);auto damage=std::max<int64_t>(1,Value(70492))/std::max<size_t>(1,near.size());for(auto other:near)Damage(other,damage);Unlock(a.pid);}Fx(a.gas?70701:70492,5,p,point,1800,10,a.entity);Destroy(a.entity);experiments.erase(experiments.begin()+i);continue;}if(Due(now,a.next)){a.next=now+2000;if(a.gas){Damage(p,Value(70672)*a.stacks);if(a.stacks)a.stacks--;if(!a.stacks){Destroy(a.entity);experiments.erase(experiments.begin()+i);continue;}}if(Walk(run,Position(p)))M::Goto(a.entity,P::GetX(p),P::GetY(p));}++i;}
  if(!professor.Transitioning()&&Due(now,nextMelee)){auto p=Resolve(PlagueTank());if(Alive(run,p)){nextMelee=now+2000;if(Distance(Position(p),Position(boss))>5.5f)M::Goto(boss,P::GetX(p),P::GetY(p));else{M::Stop(boss);M::SetRotationToXY(boss,P::GetX(p),P::GetY(p));M::SendMovePacket(boss,FUNC_ATTACK,0,P::GetX(boss),P::GetY(boss),0);Damage(p,CalcMeleeDamage(boss,p)*(berserk?6:1));}}}return !failing&&!failed;
 }
};
